def find_longest_substring(S):
    n = len(S)
    max_length = -1

    for i in range(n):
        for j in range(i + 1, n + 1):
            P = S[i:j]
            if not (S.startswith(P) or S.endswith(P)):
                max_length = max(max_length, len(P))

    return max_length

